P = [
 dict(pmid='43064294', doi='10.1016/j.envpol.2026.129566', journal='Environ Pollut', title='Predicting personal PM(2.5) exposure among community-dwelling older adults using multi-source environmental, residential, and behavioral information.', tier='B', basis='Personal / wearable', short='Fuzhou 247 adults >=60, 72-h personal PM2.5: Bayesian LASSO R2 0.48, RMSE 19.3 ug/m3; passive smoking +16.2 ug/m3 the largest predictor', design='Personal monitoring + microenvironment model', pm='72-h personal PM2.5 with concurrent outdoor PM2.5; questionnaire residential, behavioural and time-activity predictors', geo='China (Fuzhou)', endpoint='Personal PM2.5 exposure prediction', affil='Fujian Medical University, China; Fujian Medical University, China', n='247 community-dwelling adults aged >=60 in Fuzhou wore personal PM2.5 monitors for one 72-h session (summer or winter) with concurrent outdoor PM2.5 and questionnaire predictors; Bayesian LASSO. Bayesian R2 0.481 (95% CrI 0.412-0.539), RMSE 19.26 ug/m3 (18.80-19.88). Predictors with CrIs excluding zero: passive smoking only +16.2 ug/m3 (7.9-24.5), current smoking +12.9 (7.0-18.8), residence near a major road +7.4 (0.7-14.2), outdoor PM2.5 per SD +6.5 (3.8-9.4); directions stable across repeated cross-validation. Weakness: one 72-h session per person, so within-person seasonal variability is confounded with between-person predictors; monitor type and its humidity correction are not given in the abstract. Relevance: outdoor PM2.5 explains less of personal exposure than tobacco smoke at home - the argument for wearable or indoor sensors over ambient-only assignment in older cohorts.', sub=corpus.EXPO),
 dict(pmid='43064291', doi='10.1016/j.envpol.2026.129556', journal='Environ Pollut', title='Public health and economic burden of a proposed 3500-MW natural gas plant in Virginia: A PM(2.5) dispersion and impact analysis.', tier='B', basis='Model (CTM / LUR / ML)', short='Proposed 3500-MW Virginia gas plant: ~326.5 t/yr primary PM2.5, >1.2 million people exposed, USD 30.5-65 million/yr health damages; project withdrawn', design='Integrated emission-air quality-health modelling', pm='Plant-attributable PM2.5 from emission factors of comparable turbines, InMAP dispersion; COBRA health and valuation', geo='USA (Virginia, North Carolina)', endpoint='Plant-attributable PM2.5 health and economic burden', affil='Politecnico di Milano, Italy; Harvard T.H. Chan School of Public Health, USA', n="Health impact assessment of a proposed 3,500-MW natural-gas plant (Pittsylvania County, Virginia) driven by data-centre demand: emissions from operating data of comparable turbines, dispersion with InMAP, health and valuation with EPA COBRA. Estimated ~326.5 tons/yr of PM2.5 raising exposure for >1.2 million people in Virginia and North Carolina; >17,600 county residents would see increments >0.1 ug/m3 over a ~8 ug/m3 background. Annual health-related damages USD 30.5-65 million, falling disproportionately on older, lower-income and racially marginalised communities; the project was withdrawn after the findings were disseminated. Weakness: reduced-form InMAP and COBRA's national concentration-response functions, no uncertainty beyond the damage range, and secondary PM from NOx is handled only through InMAP chemistry. Relevance: increments of 0.1 ug/m3 are far below what any monitor can verify after construction; impact is modelled, never measured.", sub=corpus.BURD),
 dict(pmid='', doi='10.21203/rs.3.rs-11731419/v1', journal='Research Square', title='Examining the Association between Particulate Matter (PM2.5) Exposure and Under-five Child Mortality in India Using Cluster-Level Analysis', tier='B', basis='Satellite-fused', short='India NFHS-5 clusters: under-five mortality AOR 1.07 per 10 ug/m3 PM2.5; 1.40 above 80 vs below 40 ug/m3 (preprint)', design='Cross-sectional (multistage)', pm='Satellite-derived (NASA) global annual mean PM2.5 linked to NFHS-5 survey clusters; per 10 ug/m3 and categories', geo='India (national, NFHS-5)', endpoint='Under-five mortality', affil='University of Gour Banga, India; Mamta Health Institute for Mother and Child, India', n='Research Square preprint. NFHS-5 (2019-21) births linked at cluster level to NASA satellite-derived annual mean PM2.5; bivariate LISA for spatial clustering and survey-adjusted multivariable logistic regression. Each 10 ug/m3 PM2.5 was associated with adjusted OR 1.07 (95% CI 1.04-1.10) for under-five death; clusters above 80 ug/m3 vs below 40 ug/m3 gave AOR 1.40 (1.17-1.67), with marked spatial heterogeneity. Weakness: one annual PM2.5 value per cluster for deaths spanning five years before the survey, cross-sectional design, and the Indo-Gangetic gradient in PM2.5 tracks poverty and health-system access that survey covariates only partly capture; not peer-reviewed. Relevance: rural India is where satellite products carry the least ground truth - the case for low-cost sensor co-location to anchor these surfaces.', sub=corpus.OTHR),
 dict(pmid='43058600', doi='10.1186/s12889-026-29099-x', journal='BMC Public Health', title='Citywide re-evaluation of the Bangkok air quality health index: classification performance, nonlinear same-day respiratory associations, and implications for precautionary health communication.', tier='B', basis='Reference / regulatory monitor', short='Bangkok AQHI vs 23-hospital OPD 2021-24: poor classifier (AUC 0.35-0.54); same-day respiratory RR 1.023 at AQHI 7 vs median', design='Time-series (distributed lag non-linear)', pm='Bangkok AQHI (fixed original coefficients, multipollutant) from city monitoring; PM2.5 comparator; AQHI 7 vs citywide median', geo='Thailand (Bangkok)', endpoint='Daily outpatient respiratory, asthma, COPD and ischaemic-stroke morbidity', affil='Mahidol University, Thailand; Phramongkutklao Hospital, Thailand', n='City-wide time series of outpatient visits at 23 hospitals across 26 postcodes, 1,461 days in 2021-2024; the Bangkok AQHI applied with its original fixed coefficients; ROC analyses for high-morbidity days, negative binomial models per IQR and DLNMs over lags 0-7. Discrimination was poor: fixed-direction AUC 0.353-0.539 for the AQHI and 0.421-0.562 for PM2.5. No consistent log-linear association; DLNMs found a small same-day association at AQHI 7 vs the median for clinically selected respiratory morbidity, RR 1.023 (95% CI 1.004-1.042), surviving Bonferroni and FDR correction; cumulative lag 0-7 associations near null. Weakness: OPD counts include COVID-era service disruption, and many outcome definitions invite multiplicity despite correction. Relevance: an index built from sparse regulatory monitors classifies poorly city-wide; denser sensing is one test of whether exposure misclassification explains it.', sub=corpus.RESP),
]
